pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from (address), v (uint256), and an array of addresses for _tos
    function testFuzz_property(address from, uint256 v, address[] memory _tos) public {
        // admissible domain: _tos must be non-empty (as required by contract)
        vm.assume(_tos.length > 0);

        // Deploy a benign helper that implements transferFrom and always succeeds
        CalleeSucceeds callee = new CalleeSucceeds();

        // Call transfer and capture whether it returns true (or whether it reverts)
        bool ok;
        try c.transfer(from, address(callee), _tos, v) returns (bool ret) {
            // Completed without revert; record the returned value
            ok = ret;
        } catch {
            // If it reverted, set ok = false (but reference implementation should not revert here because callee succeeds and _tos non-empty)
            ok = false;
        }

        // The universal property: for any admissible inputs (non-empty _tos), the reference C returns true when the call completes.
        // This assert reads c's behavior (the return value captured in ok) and will hold for the reference contract for all inputs,
        // but will fail on the mutant which returns false despite successful execution.
        assertTrue(ok);
    }
}

// Minimal adversarial counterpart that responds successfully to transferFrom calls
contract CalleeSucceeds {
    // Accept any call with selector transferFrom(address,address,uint256)
    fallback() external payable {
        // do nothing and return success
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from (address), v (uint256), tosCount (uint256)
    // We will deploy a helper that returns false from its fallback to simulate a callee that does not revert but returns false.
    function testFuzz_property(address from, uint256 v, uint256 tosCount) public {
        // keep tosCount small but allow 1..5 recipients
        uint256 n = bound(tosCount, 1, 5);

        // prepare array of recipient addresses; one of them will be the adversarial callee
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            // fill with distinct addresses deterministically derived from i and from
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i)))));
        }

        // deploy a helper that, when called with selector transferFrom, DOES NOT revert but returns false (i.e. returns no data but success=false isn't possible from an internal call)
        // However low-level call returns (bool success, bytes memory) where success=false occurs when the callee executes invalid opcode or reverts; to simulate a successful call that returns false in return data,
        // we need a callee that returns a single bool false in its returned data while not reverting. The reference contract expects the low-level call to succeed (success==true) — in reference it requires success; the mutant checks success flag too but returns false if success==false. To create the distinguishing behavior we need a callee that returns success==true but returns encoded false as return data for transferFrom and the reference will still require success (which is true) — but note the original reference checks _s (the success flag), not the decoded return. The mutant change removed require and instead returns false when success flag is false. To trigger difference we need a callee that makes the low-level call succeed for some calls and fail (success==false) for others WITHOUT reverting the whole transaction. But low-level call returning success==false happens when callee reverts; that would revert the outer call unless the reference used require which would revert; the mutant would catch success==false and return false — but since the callee reverts, the outer low-level call returns success==false but does not bubble up revert because call catches it. In solidity, low-level call to a reverting callee returns (false, data) but does not revert the caller. Therefore the reference's require(_s) will revert; the mutant will detect !_s and return false. Thus to distinguish, we need a callee that for certain recipient addresses reverts (so call returns success==false) while for others returns normally (success==true).
        // Deploy a helper that reverts when given a particular "recipient" sentinel address; we will place that helper's address as caddress so every call goes to helper and helper will revert for a particular recipient index to trigger difference.

        RevertingCallee helper = new RevertingCallee();

        // choose an index to be the victim which the fuzzer can vary via tosCount and from-derived addresses; pick an index based on v to keep it fuzzed
        uint256 victimIndex = uint256(uint160(from)) % n; // depends on fuzzed from

        // set helper to revert when the target recipient equals tos[victimIndex]
        helper.setRevertFor(tos[victimIndex]);

        // Now call c.transfer with from, helper address as caddress, tos, v and observe behavior via try/catch to get whether it reverts or not
        bool okRef;
        try c.transfer(from, address(helper), tos, v) {
            okRef = true;
        } catch {
            okRef = false;
        }

        // The universal property: reference never returns false (i.e., never completes and returns false) because it either returns true or reverts; specifically, for all inputs it never successfully returns the boolean false. We observe this by checking that calls that do NOT revert must have returned true.
        // Since we only can observe via try/catch, we assert that if the call did not revert (okRef==true) then the call returned true. To make this observable in one assert, we assert that okRef implies true — but that's tautological. Instead, we assert that the call did not succeed and return false. The reference property to assert: "if the call does not revert then it returned true". We implement by re-calling via low-level staticcall on the transfer to get the returned data when it does not revert. However solidity try/catch above does not provide return data. Simpler: perform the call via low-level call on address(c) and inspect success and returned data. The reference's transfer is non-payable and public, so we can encode and call it.

        // Compose calldata for c.transfer
        bytes memory callData = abi.encodeWithSelector(bytes4(keccak256("transfer(address,address,address[],uint256)")), from, address(helper), tos, v);
        (bool lowSucc, bytes memory ret) = address(c).call(callData);

        // For the reference contract: whenever lowSucc is true (the call didn't revert), it must return abi.encode(true) — i.e., ret equals encoding of true. The mutant allows lowSucc==true with ret==abi.encode(false) or may return false by returning early when lowSucc from inner call was false but outer didn't revert; but we only need a single assert that for ALL inputs, reference returns true when not reverted. This assert will fail on mutant for some input where it returns false without reverting.
        // Single required assertion:
        // assertTrue(!(lowSucc) || (ret.length == 32 && abi.decode(ret, (bool)) == true));
        // Implement as a single assertTrue reading c by using the decoded return; this complies with the spec: single assertTrue that reads c's public behavior (call to c via address(c).call)

        bool decodedIsTrue = false;
        if (lowSucc && ret.length == 32) {
            decodedIsTrue = abi.decode(ret, (bool));
        }

        assertTrue(!lowSucc || decodedIsTrue);
    }
}

contract RevertingCallee {
    mapping(address => bool) public shouldRevert;

    // marker to set which recipient triggers revert
    function setRevertFor(address who) external {
        shouldRevert[who] = true;
    }

    // emulate function transferFrom(address,address,uint256)
    // we accept any selector and decode arguments; if recipient is marked, revert; otherwise return nothing (empty success)
    fallback() external payable {
        // decode to find the 'to' parameter which is the second address in our expected signature
        // calldata layout: 4 selector | 32 (from) | 32 (to) | 32 (v)
        if (msg.data.length >= 4 + 32*3) {
            // skip selector
            bytes memory b = msg.data;
            // extract the 2nd argument (to) at offset 4 + 32
            uint256 toWord;
            assembly {
                toWord := mload(add(b, add(4, 32)))
            }
            address to = address(uint160(toWord));
            if (shouldRevert[to]) {
                revert("forced");
            }
        }
        // otherwise return encoded true (so inner call succeeds)
        // We will return nothing (empty) which makes low-level call's success==true and empty return data; that's fine — reference only checks success flag.
    }
}

