pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the sender 'from', a value 'v' and an array length 'n' encoded via a uint8
    // The adversarial callee will return false (not revert) for a specific recipient address.
    function testFuzz_property(address from, uint256 v, uint8 n) public {
        // keep n reasonably small but allow 0 to be excluded because require(_tos.length > 0) in C
        uint256 len = bound(n, 1, 8);

        // build an array of distinct recipient addresses; we will place one special recipient that the helper returns false for
        address[] memory tos = new address[](len);
        // deploy helper that implements transferFrom returning false for a chosen recipient
        FalseReturner helper = new FalseReturner();
        // choose an index to be the failing recipient; fuzz chooses 'from' and 'v' and n only
        uint256 failIndex = uint256(uint160(from)) % len; // deterministic from fuzzed 'from'

        for (uint256 i = 0; i < len; i++) {
            // pick recipient addresses derived from 'from' and i to diversify
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, v, i)))));
        }
        // set the failing recipient in helper's internal target
        helper.setFailRecipient(tos[failIndex]);

        // Call transfer and capture whether it returns (ok=true) or reverts (ok=false).
        bool ok;
        try c.transfer(from, address(helper), tos, v) returns (bool r) {
            // the reference contract should never return false: it either reverts on a failing call or returns true
            ok = r;
        } catch {
            ok = false;
        }

        // General rule: the reference never returns false (ok == true) for any admissible inputs; the mutant can return false.
        // We assert that c.transfer did not return false. This holds for the reference for all inputs,
        // and the one-statement mutant that treats a callee false-return as a non-reverting failure will make ok == false for some inputs.
        assertTrue(ok);
    }
}

// Adversarial helper: returns false (not revert) from a call matching transferFrom(from,to,value)
contract FalseReturner {
    address public failRecipient;
    function setFailRecipient(address r) external { failRecipient = r; }

    // Implement a function matching the selector transferFrom(address,address,uint256)
    // It returns false when the 'to' equals failRecipient, otherwise returns true.
    function transferFrom(address /*from*/, address to, uint256 /*v*/) external pure returns (bool) {
        // This pure implementation cannot read failRecipient, so we use a fallback approach below instead.
        return true;
    }

    // To inspect calldata and return false for specific recipient without relying on named function, use fallback
    fallback() external returns (bytes memory) {
        // calldata layout: 4 bytes selector | 32 bytes from | 32 bytes to | 32 bytes v
        if (msg.data.length >= 4 + 32 + 32) {
            // extract 'to' from calldata
            bytes32 toWord;
            assembly { toWord := calldataload(add(4, 32)) } // skip selector and 'from'
            address to = address(uint160(uint256(toWord)));
            if (to == failRecipient) {
                // return ABI-encoded 'false' (bool false => 32 bytes zero)
                bytes memory ret = new bytes(32);
                return ret;
            }
        }
        // default return true
        bytes memory retTrue = abi.encode(true);
        return retTrue;
    }
}

