import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: from address, an array length (as uint) and a value v
    // We cannot fuzz an address to act as a callee because EOAs always succeed on .call; deploy a helper that
    // returns false from its fallback to model the adversarial counterparty.
    function testFuzz_property(address from, uint256 tosCount, uint256 v) public {
        // keep tosCount in a reasonable but wide range
        tosCount = bound(tosCount, 1, 8); // at least one recipient as required by contract

        // deploy a helper that will return false on the low-level call
        HelperReturnsFalse helper = new HelperReturnsFalse();

        // build an array of recipient addresses all pointing to the helper (so at least one call returns false)
        address[] memory tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) tos[i] = address(helper);

        // Call transfer and observe whether it returns false (without reverting) or reverts.
        // The correct contract should never return false: it either reverts on failing external call or returns true.
        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true; // completed without revert
        } catch {
            ok = false; // reverted
        }

        // General property: the reference implementation never completes and return false (i.e., it never returns false);
        // thus for all admissible inputs it holds that the call either reverts or returns true -> ok == true implies return value true.
        // We assert that the call did not complete with a boolean-false return (we detect completion via try/catch);
        // For the reference, either it reverts (ok==false) or it returned true (ok==true). The mutant can complete and return false,
        // which would make ok==true but the real return value false; however we cannot directly read that without changing signature.
        // Therefore asserting that the call did not return a false without reverting is equivalent to asserting it did not complete with a false return.

        // Exactly one assertion observing c's behavior: for the reference, any non-reverting completion implies success (true),
        // so ok==true holds only when transfer returned true; the mutant can return false while not reverting, making ok==true but semantically false —
        // to catch the mutant we deploy a callee that returns false and expect that either the correct contract reverts (ok==false) or it returned true (ok==true).
        // The universal property we can assert here is that the call does not complete successfully and silently indicate failure: i.e.,
        // when the call completes (ok==true) it must imply that the contract returned true — since we cannot read the returned bool from try, we rely on the fact
        // that for the reference implementation, calls to a callee that returns false will not complete successfully but instead revert; thus for the reference,
        // ok==true is only possible when the transfer actually succeeded. The mutant can make ok==true while meaning false, so this assertion will fail on mutant.

        assertTrue(ok);
    }
}

// Helper that returns false on any call (simulates an external token's transferFrom returning false)
contract HelperReturnsFalse {
    // fallback to return false (encoded as 0x00) with correct ABI for a bool return
    fallback() external payable returns (bytes memory) {
        // Following the correct fallback signature: return abi.encode(false);
        return abi.encode(false);
    }
}

